   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "group_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the group to record the payment in.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "A short note or description of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "receipt_file_path",
   "type": "string",
